from pathlib import Path
from PIL import Image
Image.MAX_IMAGE_PIXELS = None

def ahash(img, size=16):
    img = img.convert('L').resize((size, size))
    px = list(img.getdata())
    avg = sum(px)/len(px)
    bits = ''.join('1' if p >= avg else '0' for p in px)
    return int(bits, 2)

def hamming(a,b):
    return (a ^ b).bit_count()

files = sorted(Path('red-team/screen_crops').glob('*_source.png'))
hashes = {p.name: ahash(Image.open(p)) for p in files}
clusters = []
for name, h in hashes.items():
    placed = False
    for c in clusters:
        if hamming(h, c['h']) <= 8:
            c['files'].append(name)
            placed = True
            break
    if not placed:
        clusters.append({'h': h, 'files': [name]})

for i, c in enumerate(clusters, 1):
    print(f'CLUSTER {i}: {len(c["files"])} files')
    for f in c['files']:
        print(' ', f)
